WITH ticket AS (SELECT FanID,SUM(NetRevenueGBP) ticket_rev FROM FactTicketSales GROUP BY FanID), retail AS (SELECT FanID,SUM(NetRevenueGBP) retail_rev FROM FactRetailTransactions GROUP BY FanID), mem AS (SELECT FanID,SUM(MembershipRevenueGBP) member_rev FROM FactMembership GROUP BY FanID) SELECT COUNT(*) TotalFans,SUM(CASE WHEN d.IsMember=1 THEN 1 ELSE 0 END) Members,SUM(COALESCE(ticket_rev,0)) TicketRevenue,SUM(COALESCE(retail_rev,0)) RetailRevenue,SUM(COALESCE(member_rev,0)) MembershipRevenue,AVG(COALESCE(ticket_rev,0)+COALESCE(retail_rev,0)+COALESCE(member_rev,0)) AvgKnownRevenuePerFan FROM DimFan d LEFT JOIN ticket t ON d.FanID=t.FanID LEFT JOIN retail r ON d.FanID=r.FanID LEFT JOIN mem m ON d.FanID=m.FanID;
